fn solve(x: i8) -> u8 {
    // We'll test each quarter‐turn r = 0, 1, 2, 3
    // Compute A = normalize_mod360(-x + 90*r)
    // Deviation = min(A, 360 - A)
    // Pick the r with minimal deviation, breaking ties by smaller r.

    let input = x as i32;
    let mut best_r: u8 = 0;
    // Initialize best deviation larger than any possible (max is 180)
    let mut best_dev: i32 = 181;

    for r in 0u8..4 {
        // Compute raw angle after undoing the input rotation and applying r quarter‐turns
        let raw = -input + 90 * (r as i32);
        // Normalize into [0, 360)
        let a = raw.rem_euclid(360);
        // Deviation from vertical is the shorter way around the circle
        let dev = if a <= 180 { a } else { 360 - a };

        // Update best if strictly better
        if dev < best_dev {
            best_dev = dev;
            best_r = r;
        }
        // If dev == best_dev, we keep the smaller r because
        // we're iterating r in increasing order and only update on dev < best_dev
    }

    best_r
}

